          const frozen = store.bleSurveyFrozen.get(incomingDev.subentry_id);
          if (!frozen) continue;
          const incomingRow = (incomingDev.ble_survey_rows || []).find(
            (r) => String(r.scanner_source || "").trim().toLowerCase() === sourceNorm,
          );
          if (!incomingRow) continue;
